prompt.en:
A const binding refers to a mutable array: what is printed?

const labels = [];
labels.push("x");
console.log(labels.length);

prompt.zh:
const绑定指向可变数组：打印什么？

const labels = [];
labels.push("x");
console.log(labels.length);

prompt.en:
An inner block shadows a let binding: what is printed?

let total = 2;
{ let total = 9; }
console.log(total);

prompt.zh:
内部块遮蔽let绑定：打印什么？

let total = 2;
{ let total = 9; }
console.log(total);

prompt.en:
A returned closure keeps one counter: what is printed?

function makeStep() {
  let count = 3;
  return () => ++count;
}
const step = makeStep();
console.log(step() + ":" + step());

prompt.zh:
返回的闭包保留同一个计数器：打印什么？

function makeStep() {
  let count = 3;
  return () => ++count;
}
const step = makeStep();
console.log(step() + ":" + step());

prompt.en:
An explicit undefined uses a default parameter: what is printed?

function twice(n = 6) { return n * 2; }
console.log(twice(undefined));

prompt.zh:
显式undefined使用默认形参：打印什么？

function twice(n = 6) { return n * 2; }
console.log(twice(undefined));

prompt.en:
Two lexical declarations use the same name in one scope: choose the outcome.

let item = 1;
let item = 2;
console.log(item);

prompt.zh:
同一作用域两次声明同名词法绑定：选择结果。

let item = 1;
let item = 2;
console.log(item);

prompt.en:
A const declaration has no initializer: choose the outcome.

const limit;
console.log(limit);

prompt.zh:
const声明没有初始化表达式：选择结果。

const limit;
console.log(limit);

prompt.en:
Array map builds a new result: what is printed?

const source = [2, 5, 8];
const result = source.map(n => n + 1);
console.log(source[0] + ":" + result[0]);

prompt.zh:
数组map生成新结果：打印什么？

const source = [2, 5, 8];
const result = source.map(n => n + 1);
console.log(source[0] + ":" + result[0]);

prompt.en:
A spread copy shares a nested object: what is printed?

const source = { inner: { n: 2 } };
const copy = { ...source };
copy.inner.n = 8;
console.log(source.inner.n + ":" + (source === copy));

prompt.zh:
展开复制共享嵌套对象：打印什么？

const source = { inner: { n: 2 } };
const copy = { ...source };
copy.inner.n = 8;
console.log(source.inner.n + ":" + (source === copy));

prompt.en:
A property is inherited rather than owned: what is printed?

const parent = { n: 7 };
const child = Object.create(parent);
console.log(child.n + ":" + Object.hasOwn(child, "n"));

prompt.zh:
属性来自继承而非自有：打印什么？

const parent = { n: 7 };
const child = Object.create(parent);
console.log(child.n + ":" + Object.hasOwn(child, "n"));

prompt.en:
A Promise reaction follows the synchronous push: what is printed?

const order = [];
Promise.resolve().then(() => order.push("later"))
  .then(() => console.log(order.join(",")));
order.push("now");

prompt.zh:
Promise反应晚于同步push：打印什么？

const order = [];
Promise.resolve().then(() => order.push("later"))
  .then(() => console.log(order.join(",")));
order.push("now");

prompt.en:
Promise.all receives two fulfilled values: what is printed?

Promise.all([Promise.resolve(3), Promise.resolve(7)])
  .then(values => console.log(values.join(":")));

prompt.zh:
Promise.all接收两个已履行值：打印什么？

Promise.all([Promise.resolve(3), Promise.resolve(7)])
  .then(values => console.log(values.join(":")));

prompt.en:
An async function returns a number: what is printed?

async function four() { return 4; }
four().then(value => console.log(value + 1));

prompt.zh:
async函数返回数值：打印什么？

async function four() { return 4; }
four().then(value => console.log(value + 1));

prompt.en:
Invalid JSON is parsed inside try: what name is printed?

try {
  JSON.parse("{");
} catch (error) {
  console.log(error.name);
}

prompt.zh:
在try中解析无效JSON：打印哪个名称？

try {
  JSON.parse("{");
} catch (error) {
  console.log(error.name);
}

prompt.en:
A frozen property is assigned in an ES module: what is printed?

const box = Object.freeze({ n: 2 });
try {
  box.n = 5;
} catch (error) {
  console.log(error.name + ":" + box.n);
}

prompt.zh:
在ES模块中给冻结属性赋值：打印什么？

const box = Object.freeze({ n: 2 });
try {
  box.n = 5;
} catch (error) {
  console.log(error.name + ":" + box.n);
}
